28|async function main(): Promise<void> {
29|  loadEnv();
30|  const args = process.argv.slice(2);
31|  const bookKey = args.find((a) => !a.startsWith("--")) ?? "";
32|  const stepFlag = args.indexOf("--step");
33|  const stepArg = stepFlag === -1 ? undefined : args[stepFlag + 1];
34|  const force = args.includes("--force");
35|  if (!bookKey) throw new Error("usage: build:book <book> [--step ingest|segment|classify|cluster] [--force]");
36|  bookConfig(bookKey); // fails fast on unknown keys with the valid list
37|  const only = stepArg ?? "";
38|  if (only !== "" && !(STEPS as readonly string[]).includes(only)) {
39|    throw new Error(`unknown step "${only}", valid steps: ${STEPS.join(", ")}`);
40|  }
41|  const ctx: StepCtx = { bookKey, force, dir: join("data", "books", bookKey) };
42|  const run: Record<(typeof STEPS)[number], boolean> = {
43|    ingest: only === "" || only === "ingest",
44|    segment: only === "" || only === "segment",
45|    classify: only === "" || only === "classify",
46|    cluster: only === "" || only === "cluster",
47|  };
48|  if (run.ingest) {
49|    const book = await runIngest(ctx);
50|    console.log(`ingest: ${book.chapters.length} chapters, ${book.paragraphs.length} paragraphs, ${book.textVersion}`);
51|  }
52|  if (run.segment) {
53|    const meta = createMetaClient({ apiKey: env("META_API_KEY"), model: process.env.META_MODEL ?? "muse-spark-1.3-contributor" });
54|    console.log(`segment: ${meta.model}`);
55|    const scenes = await runSegment(ctx, { meta });
56|    console.log(`segment: ${scenes.length} scenes`);
57|  }
58|  if (run.classify) {
59|    const meta = createMetaClient({ apiKey: env("META_API_KEY"), model: process.env.META_MODEL ?? "muse-spark-1.3-contributor" });
60|    const jev = createJevClient({ apiKey: env("JEV_API_KEY"), model: process.env.JEV_MODEL ?? "jev-1.14.0" });
61|    const scenes = await runClassify(ctx, { jev, meta });
62|    const overrides = scenes.filter((s) => s.muse_override !== null).length;
63|    const failures = scenes.filter((s) => s.final === null).length;
64|    console.log(`classify: ${scenes.length} scenes, ${overrides} overrides, ${failures} failures`);
65|  }
66|  if (run.cluster) {
67|    await runCluster(ctx);
68|    console.log("cluster: wrote music-clusters.json");
69|  }
70|  printSummary(ctx.dir);
71|}
72|
73|function printSummary(dir: string): void {
74|  const book = JSON.parse(readFileSync(join(dir, "book.json"), "utf8")) as {
75|    chapters: unknown[];
76|    paragraphs: unknown[];
77|  };
78|  let scenes: { final: { vector: Record<string, number> } | null }[] = [];
79|  let overrideRate = 0;
80|  let jev = { cost_usd: 0 };
81|  let meta = { cost_usd: 0 };
82|  let total = 0;
83|  try {
84|    const analysis = JSON.parse(readFileSync(join(dir, "analysis.json"), "utf8")) as {
85|      scenes: (typeof scenes)[number][];
86|      override_rate: number;
87|      provenance: { jev: typeof jev; meta: typeof meta; total_cost_usd: number };
88|    };
89|    scenes = analysis.scenes;
90|    overrideRate = analysis.override_rate;
91|    jev = analysis.provenance.jev;
92|    meta = analysis.provenance.meta;
93|    total = analysis.provenance.total_cost_usd;
94|  } catch {
95|    // Steps after ingest may not have run yet.
96|  }
97|  const dist = new Map<string, number>();
98|  let failures = 0;
99|  for (const scene of scenes) {
100|    if (!scene.final) {
101|      failures += 1;
102|      continue;
103|    }
104|    const top = Object.entries(scene.final.vector).sort((a, b) => b[1] - a[1])[0]?.[0] ?? "?";
105|    dist.set(top, (dist.get(top) ?? 0) + 1);
106|  }
107|  console.log(`summary: ${book.chapters.length} chapters, ${book.paragraphs.length} paragraphs, ${scenes.length} scenes`);
108|  console.log(`emotions: ${[...dist.entries()].map(([id, count]) => `${id} ${count}`).join(", ") || "none yet"}`);
109|  console.log(`override rate ${((overrideRate ?? 0) * 100).toFixed(1)}%, failures ${failures}`);
110|  console.log(`cost: jev $${(jev.cost_usd ?? 0).toFixed(4)}, meta $${(meta.cost_usd ?? 0).toFixed(4)}, total $${(total ?? 0).toFixed(4)}`);
111|}
112|
113|main().catch((error: unknown) => {
114|  console.error(`error: ${(error as Error).message}`);
115|  process.exit(1);
116|});

