1|// Step 4: cluster classified scenes into about 15 track prompts.
2|// No network in this step and no audio code anywhere.
3|import { readFileSync, writeFileSync } from "node:fs";
4|import { join } from "node:path";
5|import { buildFeatures, dominantIndex, kmeans } from "../core/cluster";
6|import type { WeightedPoint } from "../core/cluster";
7|import { bpmRange, buildTrackPrompt } from "../core/music-prompt";
8|import { EMOTIONS, FEATURE_WEIGHTS } from "../core/types";
9|import type { AnalyzedScene, Book, EmotionId } from "../core/types";
10|import { readIfFresh } from "./cache";
11|import type { StepCtx } from "./ingest";
12|
13|const SEED = 42;
14|
15|export async function runCluster(ctx: StepCtx): Promise<void> {
16|  const book = JSON.parse(readFileSync(join(ctx.dir, "book.json"), "utf8")) as Book;
17|  const analysis = JSON.parse(readFileSync(join(ctx.dir, "analysis.json"), "utf8")) as {
18|    scenes: AnalyzedScene[];
19|  };
20|  const outPath = join(ctx.dir, "music-clusters.json");
21|  if (!ctx.force && readIfFresh(outPath, book.textVersion)) return;
22|  const classified = analysis.scenes.filter((s): s is AnalyzedScene & { final: NonNullable<AnalyzedScene["final"]> } => s.final !== null);
23|  const byId = new Map(classified.map((s) => [s.id, s]));
24|  const unclustered = analysis.scenes.filter((s) => s.final === null).map((s) => s.id);
25|  const points: WeightedPoint[] = classified.map((s) => ({
26|    sceneId: s.id,
27|    features: buildFeatures({ vector: s.final.vector, intensity: s.final.intensity, tempo: s.final.tempo }),
28|  }));
29|  const k = Math.min(15, points.length);
30|  const clusters = kmeans(points, k, { seed: SEED, restarts: 20, maxIter: 100 })
31|    .map((cluster) => {
32|      const intensity = Math.min(1, Math.max(0, (cluster.centroid[8] ?? 0) / FEATURE_WEIGHTS.intensity));
33|      const tempo = Math.min(1, Math.max(0, (cluster.centroid[9] ?? 0) / FEATURE_WEIGHTS.tempo));
34|      return { cluster, intensity, tempo, dominant: dominantIndex(cluster.centroid) };
35|    })
36|    .sort((a, b) => a.dominant - b.dominant || a.intensity - b.intensity)
37|    .map(({ cluster, intensity, tempo }, index) => {
38|      const vector = Object.fromEntries(EMOTIONS.map((id, i) => [id, cluster.centroid[i] ?? 0]));
39|      const ranked = (Object.entries(vector) as [EmotionId, number][]).sort((a, b) => b[1] - a[1]);
40|      const scenes = cluster.points
41|        .map((p) => byId.get(p.sceneId))
42|        .filter((s) => s !== undefined)
43|        .sort((a, b) => a.start_n - b.start_n)
44|        .map((s) => s.id);
45|      return {
46|        id: `t${String(index + 1).padStart(2, "0")}`,
47|        size: cluster.points.length,
48|        centroid: { vector, intensity, tempo },
49|        dominant: ranked.slice(0, 2).map(([id]) => id),
50|        bpm: bpmRange(tempo),
51|        scenes,
52|        prompt: buildTrackPrompt({ top: ranked.slice(0, 3).map(([id, weight]) => ({ id, weight })), intensity, tempo }),
53|      };
54|    });
55|  writeFileSync(
56|    outPath,
57|    `${JSON.stringify({ bookId: book.id, textVersion: book.textVersion, k, seed: SEED, feature_weights: FEATURE_WEIGHTS, clusters, unclustered, provenance: { date: new Date().toISOString() } })}\n`,
58|  );
59|}

